// ============================================
// VALIDATION INPUT (RFC-004)
// ============================================

const input = $input.first().json;
const body = input.body || {};
const headers = input.headers || {};

// --- Extract Tenant ID ---
const tenantId = headers['x-tenant-id'] 
  || headers['X-Tenant-ID'] 
  || headers['X-Tenant-Id']
  || $env.DEFAULT_TENANT_ID
  || 'default';

// --- Validation required fields ---
if (!body.discord_user_id) {
  return {
    error: true,
    error_code: 'MISSING_USER_ID',
    message: 'Le champ "discord_user_id" est requis',
    http_status: 400
  };
}

if (!body.guild_id) {
  return {
    error: true,
    error_code: 'MISSING_GUILD_ID',
    message: 'Le champ "guild_id" est requis',
    http_status: 400
  };
}

if (!body.old_channel_id) {
  return {
    error: true,
    error_code: 'MISSING_OLD_CHANNEL_ID',
    message: 'Le champ "old_channel_id" est requis',
    http_status: 400
  };
}

// --- Return validated data ---
return {
  error: false,
  data: {
    discord_user_id: body.discord_user_id,
    guild_id: body.guild_id,
    old_channel_id: body.old_channel_id,
    channel_type: body.channel_type || 'support',
    tenant_id: tenantId,
    metadata: {
      ...body.metadata,
      recreated_from: body.old_channel_id,
      reason: 'unknown_channel_error'
    }
  }
};

// ============================================
// FORMAT RECREATED CHANNEL RESPONSE
// ============================================

const apiResponse = $input.first().json;
const channelData = apiResponse.data || apiResponse;
const oldChannelId = $('Validate Input').first().json.data.old_channel_id;

return {
  success: true,
  status: 'recreated',
  channel: {
    channel_id: channelData.channel_id,
    channel_type: channelData.channel_type,
    channel_name: channelData.channel_name,
    is_active: channelData.is_active
  },
  previous_channel_id: oldChannelId
};

// ============================================
// FORMAT VALIDATION ERROR
// ============================================

const input = $input.first().json;

return {
  success: false,
  error: {
    code: input.error_code || 'VALIDATION_ERROR',
    message: input.message || 'Erreur de validation'
  },
  http_status: input.http_status || 400
};

// ============================================
// FORMAT CHATBOT-CORE ERROR
// ============================================

const input = $input.first().json;

// Map chatbot-core errors
const errorCode = input.error?.code || input.code || 'DISCORD_ERROR';
let httpStatus = 500;
let message = input.error?.message || input.message || 'Erreur lors de la recréation du channel Discord';

switch(errorCode) {
  case 'MISSING_FIELD':
  case 'INVALID_CHANNEL_TYPE':
    httpStatus = 400;
    break;
  case 'UNAUTHORIZED':
    httpStatus = 401;
    message = 'Authentification chatbot-core invalide';
    break;
  case 'GUILD_NOT_FOUND':
    httpStatus = 404;
    message = 'Serveur Discord non trouvé ou bot non présent';
    break;
  case 'MEMBER_NOT_FOUND':
    httpStatus = 404;
    message = 'Utilisateur non trouvé sur le serveur Discord';
    break;
  case 'PERMISSION_DENIED':
    httpStatus = 403;
    message = 'Le bot n\'a pas les permissions pour créer le channel';
    break;
}

return {
  success: false,
  error: {
    code: errorCode,
    message: message
  },
  http_status: httpStatus
};
